examples.template:
VStack(alignment: .leading, spacing: theme.spacing.space3) {
    Text({{message}})
        .monarchTextStyle(.body)
        .foregroundStyle(theme.colors.textDefault)
    MonarchAiFollowUpSuggestions([{{suggestions.0}}, {{suggestions.1}}, {{suggestions.2}}]) { question in
        draft = question
    }
}
.padding(.horizontal)

examples.code:
VStack(alignment: .leading, spacing: theme.spacing.space3) {
    Text("The quarterly plan has three goals and a launch in week 9.")
        .monarchTextStyle(.body)
        .foregroundStyle(theme.colors.textDefault)
    MonarchAiFollowUpSuggestions(["Make it shorter", "Add a timeline", "Who owns each goal?"]) { question in
        draft = question
    }
}
.padding(.horizontal)
